using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The Isle: Evrima RCON (TCP, not Source RCON). Login = 0x01 + password + 0x00, answered "Password Accepted";
// a command = 0x02 + one opcode byte + its arguments + 0x00. Type "help" for the command list.
var opcodes = new Dictionary<string, byte>(StringComparer.OrdinalIgnoreCase)
{
    ["announce"] = 0x10, ["directmessage"] = 0x11, ["serverdetails"] = 0x12, ["wipecorpses"] = 0x13,
    ["getplayables"] = 0x14, ["updateplayables"] = 0x15, ["togglemigrations"] = 0x19, ["ban"] = 0x20,
    ["togglegrowthmultiplier"] = 0x21, ["setgrowthmultiplier"] = 0x22, ["togglenetupdatedistancechecks"] = 0x23,
    ["kick"] = 0x30, ["playerlist"] = 0x40, ["save"] = 0x50, ["pause"] = 0x60, ["custom"] = 0x70,
    ["getplayerdata"] = 0x77, ["togglewhitelist"] = 0x81, ["addwhitelist"] = 0x82, ["removewhitelist"] = 0x83,
    ["toggleglobalchat"] = 0x84, ["togglehumans"] = 0x86, ["toggleai"] = 0x90, ["disableaiclasses"] = 0x91,
    ["aidensity"] = 0x92, ["getqueuestatus"] = 0x93, ["toggleailearning"] = 0x94,
};

async Task<string> ReadReply(NetworkStream stream, TcpClient client, int quietMs, int maxMs)
{
    var buffer = new byte[16384];
    var output = new MemoryStream();
    var hardEnd = DateTime.UtcNow.AddMilliseconds(maxMs);
    var lastData = DateTime.UtcNow;
    while (DateTime.UtcNow < hardEnd && (output.Length == 0 || DateTime.UtcNow - lastData < TimeSpan.FromMilliseconds(quietMs)))
    {
        if (stream.DataAvailable)
        {
            var n = stream.Read(buffer, 0, buffer.Length);
            if (n <= 0) break;
            output.Write(buffer, 0, n);
            lastData = DateTime.UtcNow;
        }
        else
        {
            if (client.Client.Poll(0, SelectMode.SelectRead) && client.Client.Available == 0) break; // closed by the server
            await Task.Delay(50);
        }
    }
    return Encoding.UTF8.GetString(output.ToArray()).Replace("\0", "").Trim();
}

var result = "";
try
{
    var line = (Globals.Variables.Parse<string>("Command") ?? "").Trim();
    var space = line.IndexOf(' ');
    var name = space < 0 ? line : line.Substring(0, space);
    var arguments = space < 0 ? "" : line.Substring(space + 1).Trim();

    if (name.Length == 0 || name.Equals("help", StringComparison.OrdinalIgnoreCase))
    {
        result = "Evrima RCON commands: " + string.Join(", ", opcodes.Keys.OrderBy(k => k)) +
                 "\nExamples: announce Hello everyone | playerlist | save | kick <SteamID>,<reason> | ban <name>,<SteamID>,<reason>,<minutes>";
    }
    else if (!opcodes.TryGetValue(name, out var opcode))
    {
        result = "Unknown command '" + name + "'. Type help for the list.";
    }
    else
    {
        var address = Globals.Variables.Parse<string>("Address");
        var port = Globals.Variables.Parse<int>("Port");
        var password = Globals.Variables.Parse<string>("Password") ?? "";

        using var client = new TcpClient();
        var connect = client.ConnectAsync(address, port);
        if (await Task.WhenAny(connect, Task.Delay(5000)) != connect)
            throw new Exception("timed out connecting to " + address + ":" + port);
        await connect;
        var stream = client.GetStream();

        var login = new List<byte> { 0x01 };
        login.AddRange(Encoding.UTF8.GetBytes(password));
        login.Add(0x00);
        await stream.WriteAsync(login.ToArray(), 0, login.Count);
        var auth = await ReadReply(stream, client, 300, 5000);
        if (auth.IndexOf("Accepted", StringComparison.OrdinalIgnoreCase) < 0)
            throw new Exception("login refused (" + (auth.Length == 0 ? "no reply" : auth) + ")");

        var packet = new List<byte> { 0x02, opcode };
        packet.AddRange(Encoding.UTF8.GetBytes(arguments));
        packet.Add(0x00);
        await stream.WriteAsync(packet.ToArray(), 0, packet.Count);
        result = await ReadReply(stream, client, 750, 8000);
        if (result.Length == 0) result = name + " sent.";
    }
}
catch (Exception ex)
{
    result = "Evrima RCON error: " + ex.Message;
}
Globals.ReturnValue = result;

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll, System.Net.Http.dll, System.IO.Compression.dll, System.IO.Compression.ZipFile.dll, System.Diagnostics.Process.dll
using System;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Global graceful-stop helper (Windows). On BeforeServiceStopped, send Ctrl+C (SIGINT)
// to the running game-server process via windows-kill.exe so it shuts down cleanly before
// TCAdmin performs its own stop. windows-kill.exe is downloaded on demand into the hidden
// {serviceroot}/.tca folder (so the customer never sees it) and reused on later stops.

// Only game services expose a single tracked process id; skip anything else (Docker/base).
var gameService = (object)ThisService as GameService;
if (gameService == null)
{
    ScriptConsole.WriteLine("Not a game service; skipping graceful Ctrl+C stop.");
    return;
}

int? pid = gameService.ProcessId;
if (pid == null || pid <= 0)
{
    ScriptConsole.WriteLine("No running process id for this service; nothing to stop.");
    return;
}

// Keep windows-kill.exe in the hidden .tca folder so it isn't visible to the user.
string toolDir = Path.Combine(RootDirectory, ".tca");
string killExe = Path.Combine(toolDir, "windows-kill.exe");

// Download windows-kill.exe on demand if it isn't cached yet.
if (!File.Exists(killExe))
{
    const string url = "https://github.com/ElyDotDev/windows-kill/releases/download/1.1.4/windows-kill_1.1.4_release.zip";
    const string entryPath = "windows-kill_x64_1.1.4_lib_release/windows-kill.exe";

    try
    {
        Directory.CreateDirectory(toolDir);
        string zipPath = Path.Combine(toolDir, "windows-kill_1.1.4_release.zip");

        ScriptConsole.WriteLine($"windows-kill.exe not found; downloading {url}");
        using (var http = new HttpClient())
        {
            byte[] data = await http.GetByteArrayAsync(url, ThisCancellationToken);
            await File.WriteAllBytesAsync(zipPath, data, ThisCancellationToken);
        }

        using (ZipArchive archive = ZipFile.OpenRead(zipPath))
        {
            ZipArchiveEntry entry = archive.GetEntry(entryPath);
            if (entry == null)
                throw new Exception($"Entry '{entryPath}' not found in the archive.");
            entry.ExtractToFile(killExe, overwrite: true);
        }
        ScriptConsole.WriteLine($"Extracted windows-kill.exe to {killExe}");

        try { File.Delete(zipPath); }
        catch (Exception ex) { ScriptConsole.WriteLine($"Warning: could not delete zip file: {ex.Message}"); }
    }
    catch (Exception ex)
    {
        ScriptConsole.WriteLine($"Failed to download windows-kill.exe: {ex.Message}; skipping graceful Ctrl+C stop.");
        return;
    }
}

// Send Ctrl+C (SIGINT) to the running game process.
ScriptConsole.WriteLine($"Sending SIGINT (Ctrl+C) to process {pid} via windows-kill.exe");
var psi = new ProcessStartInfo
{
    FileName = killExe,
    Arguments = $"-SIGINT {pid}",
    WorkingDirectory = RootDirectory,
    UseShellExecute = false,
    CreateNoWindow = true,
    RedirectStandardOutput = true,
    RedirectStandardError = true
};

try
{
    using var killer = Process.Start(psi);
    if (killer != null)
        await killer.WaitForExitAsync(ThisCancellationToken);
}
catch (Exception ex)
{
    ScriptConsole.WriteLine($"Failed to run windows-kill.exe: {ex.Message}");
    return;
}

// Wait up to 60s for the process to exit before TCAdmin proceeds with its own stop.
const int maxChecks = 60;
for (int count = 1; count <= maxChecks; count++)
{
    bool running;
    try
    {
        using var proc = Process.GetProcessById(pid.Value);
        running = !proc.HasExited;
    }
    catch (ArgumentException)
    {
        running = false; // process no longer exists
    }

    if (!running)
    {
        ScriptConsole.WriteLine($"Process {pid} has exited after {count} second(s).");
        return;
    }

    await Task.Delay(TimeSpan.FromSeconds(1), ThisCancellationToken);
}

ScriptConsole.WriteLine($"WARNING: process {pid} did not exit within {maxChecks} seconds.");
